"""部署升级后兼容旧加密数据与混合存储，所有数据来自隔离测试库。"""
from datetime import timedelta

import pytest
from cryptography.exceptions import InvalidTag
from sqlalchemy import select

from app.models import Attachment
from app.services import ai_key, ai_images
from app.services.image_storage import ImageStorage
from app.tests.conftest import login
from app.tests.test_attachment import upload, ah, ADMIN
from app.time import utcnow


def test_cryptography_upgrade_reads_46_0_3_ciphertext_and_keeps_aad_boundary():
    # Generated by cryptography 46.0.3; fixed dummy payload, never a real user key.
    legacy = 'wAo75kdoI6WDKBbQKE2OJNG1hYXLWclDnsBqt9rJadygKld/MD8VY+WwCoeSm+I/IJI='
    assert ai_key.decrypt('legacy-fixture-secret', legacy, '42') == 'fixture-provider-token'
    with pytest.raises(InvalidTag):
        ai_key.decrypt('legacy-fixture-secret', legacy, '43')
    with pytest.raises(InvalidTag):
        ai_key.decrypt('different-fixture-secret', legacy, '42')
    fresh = ai_key.encrypt('legacy-fixture-secret', 'new-fixture', '42')
    assert ai_key.decrypt('legacy-fixture-secret', fresh, '42') == 'new-fixture'


def test_legacy_local_image_survives_qiniu_switch_and_reclaim_uses_actual_backend(client, monkeypatch):
    token = login(client, **ADMIN)
    headers = ah(token['access_token'])
    key = upload(client, '/api/v1/attachments/image', headers, biz='mistake').json()['data']['key']
    local_path = client.app.state.settings.image_directory / key
    original = local_path.read_bytes()
    settings = client.app.state.settings
    settings.image_storage = 'qiniu'
    settings.environment = 'production'
    monkeypatch.setattr(ImageStorage, '_s3_client', lambda *a: pytest.fail('Legacy local image must not access Qiniu'))
    response = client.get('/api/v1/attachments/view', headers=headers, params={'key': key})
    assert response.status_code == 200 and response.content == original
    assert client.get('/api/v1/attachments/view', params={'key': key}).status_code == 401
    with client.app.state.session_factory() as db:
        assert ai_images.user_content(db, settings, token['user']['id'], '题目', [key])[1]['image_url']['url'].startswith('data:image/jpeg;base64,')
        row = db.scalar(select(Attachment).where(Attachment.object_key == key))
        row.created_at = utcnow() - timedelta(hours=25)
        db.commit()
    result = client.post('/api/v1/attachments/reclaim', headers=headers)
    assert result.status_code == 200 and result.json()['data']['deleted'] == 1
    assert not local_path.exists()


def test_qiniu_attachment_remains_cloud_backed_if_default_changes(client, monkeypatch, tmp_path):
    token = login(client, **ADMIN)
    headers = ah(token['access_token'])
    key = upload(client, '/api/v1/attachments/image', headers, biz='mistake').json()['data']['key']
    with client.app.state.session_factory() as db:
        row = db.scalar(select(Attachment).where(Attachment.object_key == key))
        row.storage_backend = 'qiniu'
        db.commit()
    calls = []
    monkeypatch.setattr(ImageStorage, 'read_private', lambda storage, k: calls.append((storage.s.image_storage, k)) or b'cloud-fixture')
    response = client.get('/api/v1/attachments/view', headers=headers, params={'key': key})
    assert response.content == b'cloud-fixture'
    assert calls == [('qiniu', key)]
    from app.services.backup import create_backup, verify_and_restore
    manifest = verify_and_restore(create_backup(client.app.state.settings, tmp_path / 'backup'))
    assert not manifest['objects_included']  # Local default must not claim cloud bytes were backed up.
    assert not manifest['remote_objects_included']
